-- 已发出的设备操作意图增加终态 settled。cancelled 仍只表示从未下发的 reserved。
IF EXISTS (SELECT 1 FROM sys.check_constraints WHERE name = N'ck_device_intent_phase' AND parent_object_id = OBJECT_ID(N'gb_device_operation_intent'))
  ALTER TABLE [gb_device_operation_intent] DROP CONSTRAINT [ck_device_intent_phase];
IF NOT EXISTS (SELECT 1 FROM sys.check_constraints WHERE name = N'ck_device_intent_phase' AND parent_object_id = OBJECT_ID(N'gb_device_operation_intent'))
  ALTER TABLE [gb_device_operation_intent] ADD CONSTRAINT [ck_device_intent_phase] CHECK ((([updated_at] >= [created_at]) and ((([state] = 'reserved') and ([row_version] = 1) and ([dispatch_started_at] is null) and ([cancelled_at] is null)) or (([state] = 'dispatched') and ([row_version] >= 2) and ([cancelled_at] is null) and ([dispatch_started_at] is not null) and ([dispatch_started_at] >= [created_at]) and ([dispatch_started_at] <= [updated_at])) or (([state] = 'cancelled') and ([row_version] >= 2) and ([dispatch_started_at] is null) and ([cancelled_at] is not null) and ([cancelled_at] >= [created_at]) and ([cancelled_at] <= [updated_at])) or (([state] = 'settled') and ([row_version] >= 3) and ([cancelled_at] is null) and ([dispatch_started_at] is not null) and ([dispatch_started_at] >= [created_at]) and ([dispatch_started_at] <= [updated_at])))));
